|$)" , body ) if type_match : info [ "type" ] = type_match . group ( 1 ) . strip () chapter_match = re . search ( r "目标章节\*\*:\s*(.+?)(?:
|$)" , body ) if chapter_match : info [ "chapter" ] = chapter_match . group ( 1 ) . strip () attr_match = re . search ( r "署名\*\*:\s*(.+?)(?:
|$)" , body ) if attr_match : info [ "attribution" ] = attr_match . group ( 1 ) . strip () return info def generate_page ( issue : dict , output_dir : Path ) -> str : """为单个投稿生成 Markdown 页面。""" number = issue [ "number" ] title = issue [ "title" ] . replace ( "[投稿]" , "" ) . strip () body = issue [ "body" ] or "" info = parse_issue_body ( body ) created = issue [ "created_at" ][: 10 ] # 提取正文（标题之后的内容） content = body separator_match = re . search ( r "^---\s*$" , body , re . MULTILINE ) if separator_match : content = body [ separator_match . end ():] . strip () frontmatter = textwrap . dedent ( f """ \ --- status: community author: { info [ 'attribution' ] } source_issue: { issue [ 'html_url' ] } submission_date: { created } title: { title } --- """ ) page = f " { frontmatter } 

 # { title } 

