 " output_file = output_dir / f " { number } .md" output_file . write_text ( page , encoding = "utf-8" ) return str ( output_file ) def generate_index ( issues : list [ dict ], output_dir : Path ) -> None : """生成社区角首页，展示所有投稿的卡片列表。""" lines = [ "# 社区角" , "" , "这里展示来自社区投稿的内容，未经团队深度审核，仅供交流参考。" , "" , ] if not issues : lines . append ( "*暂无社区投稿。快来[提交你的第一篇投稿](/submit/)吧！*" ) else : for issue in issues : number = issue [ "number" ] title = issue [ "title" ] . replace ( "[投稿]" , "" ) . strip () info = parse_issue_body ( issue [ "body" ] or "" ) created = issue [ "created_at" ][: 10 ] lines . append ( f "## [ { title } ]( { number } .md)" ) lines . append ( "" ) lines . append ( f "投稿者： { info [ 'attribution' ] } · " f "类型： { info [ 'type' ] } · " f "日期： { created } " ) if info [ "chapter" ] and info [ "chapter" ] != "未指定" : lines . append ( f " · 目标章节： { info [ 'chapter' ] } " ) lines . append ( "" ) lines . append ( "---" ) lines . append ( "" ) output_file = output_dir / "index.md" output_file . write_text ( " 
